31	export async function getProducts(rawQuery: unknown) {
32	  const parseResult = ProductQuerySchema.safeParse(rawQuery);
33	  if (!parseResult.success) {
34	    throw new Error("Paramètres de requête invalides");
35	  }
36	
37	  const { category, search, minPrice, maxPrice, sort, page, limit } = parseResult.data;
38	
39	  const where: Prisma.ProductWhereInput = {
40	    isActive: true,
41	  };
42	
43	  if (category) {
44	    where.category = {
45	      slug: category,
46	    };
47	  }
48	
49	  if (search) {
50	    where.OR = [
51	      { titleFr: { contains: search, mode: "insensitive" } },
52	      { descriptionFr: { contains: search, mode: "insensitive" } },
53	    ];
54	  }
55	
56	  if (minPrice !== undefined || maxPrice !== undefined) {
57	    where.price = {};
58	    if (minPrice !== undefined) where.price.gte = minPrice;
59	    if (maxPrice !== undefined) where.price.lte = maxPrice;
60	  }
61	
62	  let orderBy: Prisma.ProductOrderByWithRelationInput = { createdAt: "desc" };
63	  if (sort === "price-asc") orderBy = { price: "asc" };
64	  if (sort === "price-desc") orderBy = { price: "desc" };
65	
66	  const [products, total] = await Promise.all([
67	    prisma.product.findMany({
68	      where,
69	      include: {
70	        category: true,
71	        variants: true,
72	        images: true,
73	        inventory: true,
74	      },
75	      orderBy,
76	      skip: (page - 1) * limit,
77	      take: limit,
78	    }),
79	    prisma.product.count({ where }),
80	  ]);
81	
82	  return {
83	    products,
84	    pagination: {
85	      total,
86	      page,
87	      limit,
88	      totalPages: Math.ceil(total / limit),
89	    },
90	  };
91	}
