3	import { useState } from "react";
4	import { Search, ArrowUpDown, ChevronLeft, ChevronRight, X } from "lucide-react";
5	import { ProductCard, ProductCardProps } from "@/components/ProductCard";
6	
7	export interface SearchFilterSortProps {
8	  initialProducts: ProductCardProps[];
9	}
10	
11	export function SearchFilterSort({ initialProducts }: SearchFilterSortProps) {
12	  const [searchQuery, setSearchQuery] = useState("");
13	  const [selectedCategory, setSelectedCategory] = useState("all");
14	  const [sortBy, setSortBy] = useState("popular");
15	  const [currentPage, setCurrentPage] = useState(1);
16	  const itemsPerPage = 8;
17	
18	  // Filter products
19	  const filtered = initialProducts.filter((p) => {
20	    const matchesQuery = p.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
21	                         p.category.toLowerCase().includes(searchQuery.toLowerCase());
22	    const matchesCat = selectedCategory === "all" || p.category.toLowerCase().includes(selectedCategory.toLowerCase());
23	    return matchesQuery && matchesCat;
24	  });
25	
26	  // Sort products
27	  const sorted = [...filtered].sort((a, b) => {
28	    if (sortBy === "price-asc") return a.price - b.price;
29	    if (sortBy === "price-desc") return b.price - a.price;
30	    if (sortBy === "rating") return (b.rating ?? 0) - (a.rating ?? 0);
31	    return 0; // popular
32	  });
33	
34	  // Pagination
35	  const totalPages = Math.ceil(sorted.length / itemsPerPage) || 1;
36	  const paginated = sorted.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);
37	
38	  return (
39	    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
40	      {/* Search Header */}
41	      <div className="bg-orange-50 border border-orange-100 rounded-3xl p-8 text-center space-y-4">
42	        <h1 className="text-3xl font-black text-slate-900">Recherche & Catalogue</h1>
43	        <p className="text-slate-600 max-w-xl mx-auto text-sm sm:text-base">
44	          Trouvez rapidement le produit idéal pour vos enfants parmi notre sélection au Maroc.
45	        </p>
46	
47	        {/* Search Bar Input */}
48	        <div className="relative max-w-2xl mx-auto">
49	          <input
50	            type="text"
51	            value={searchQuery}
52	            onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
53	            placeholder="Rechercher par nom, catégorie, marque..."
54	            className="w-full bg-white border border-slate-200 rounded-full py-3.5 ps-12 pe-10 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-orange-500 transition-all"
55	          />
56	          <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
57	          {searchQuery && (
58	            <button
59	              onClick={() => setSearchQuery("")}
60	              className="absolute end-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
61	            >
62	              <X className="w-4 h-4" />
63	            </button>
64	          )}
65	        </div>
66	      </div>
67	
68	      {/* Filter and Sort Controls Bar */}
69	      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white border border-slate-200 p-4 rounded-2xl shadow-xs">
70	        {/* Category Pills */}
71	        <div className="flex items-center gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0">
72	          {[
73	            { label: "Tous", value: "all" },
74	            { label: "Vêtements", value: "vêtements" },
75	            { label: "Jouets", value: "jouets" },
76	            { label: "Puériculture", value: "puériculture" },
77	            { label: "Repas", value: "repas" },
78	          ].map((cat) => (
79	            <button
80	              key={cat.value}
81	              onClick={() => { setSelectedCategory(cat.value); setCurrentPage(1); }}
82	              className={`px-4 py-2 rounded-full text-xs font-semibold whitespace-nowrap transition-colors ${
83	                selectedCategory === cat.value
84	                  ? "bg-orange-600 text-white shadow-sm"
85	                  : "bg-slate-100 text-slate-600 hover:bg-slate-200"
86	              }`}
87	            >
88	              {cat.label}
89	            </button>
90	          ))}
91	        </div>
92	
93	        {/* Sort Dropdown */}
94	        <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-end">
95	          <div className="flex items-center gap-2 text-sm text-slate-500">
96	            <ArrowUpDown className="w-4 h-4" />
97	            <span>Trier par:</span>
98	          </div>
99	          <select
100	            value={sortBy}
101	            onChange={(e) => setSortBy(e.target.value)}
102	            className="bg-slate-100 border border-slate-200 rounded-xl px-3 py-2 text-sm font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-orange-500"
103	          >
104	            <option value="popular">Pertinence / Popularité</option>
105	            <option value="price-asc">Prix croissant</option>
106	            <option value="price-desc">Prix décroissant</option>
107	            <option value="rating">Meilleures notes</option>
108	          </select>
109	        </div>
110	      </div>
111	
112	      {/* Results Count */}
113	      <div className="flex justify-between items-center text-xs text-slate-500 px-1">
114	        <span>{sorted.length} article(s) trouvé(s)</span>
115	        <span>Page {currentPage} sur {totalPages || 1}</span>
116	      </div>
117	
118	      {/* Product Grid */}
119	      {paginated.length > 0 ? (
120	        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
121	          {paginated.map((prod) => (
122	            <ProductCard key={prod.id} {...prod} />
123	          ))}
124	        </div>
125	      ) : (
126	        <div className="text-center py-20 bg-white border border-slate-200 rounded-2xl shadow-xs space-y-3">
127	          <p className="text-slate-900 font-bold text-lg">Aucun produit ne correspond à vos critères</p>
128	          <p className="text-sm text-slate-500">Essayez de modifier vos filtres ou votre recherche.</p>
129	          <button
130	            onClick={() => { setSearchQuery(""); setSelectedCategory("all"); setCurrentPage(1); }}
131	            className="mt-4 bg-orange-600 text-white font-medium px-6 py-2.5 rounded-full text-sm hover:bg-orange-700 transition-colors shadow-sm"
132	          >
133	            Réinitialiser les filtres
134	          </button>
135	        </div>
136	      )}
137	
138	      {/* Pagination Controls */}
139	      {totalPages > 1 && (
140	        <div className="flex justify-center items-center gap-2 pt-6">
141	          <button
142	            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
143	            disabled={currentPage === 1}
144	            className="p-2 border border-slate-200 rounded-xl bg-white text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
145	          >
146	            <ChevronLeft className="w-5 h-5" />
147	          </button>
148	
149	          {[...Array(totalPages)].map((_, idx) => (
150	            <button
151	              key={idx}
152	              onClick={() => setCurrentPage(idx + 1)}
153	              className={`w-10 h-10 rounded-xl font-bold text-sm transition-colors ${
154	                currentPage === idx + 1
155	                  ? "bg-orange-600 text-white shadow-sm"
156	                  : "bg-white border border-slate-200 text-slate-700 hover:bg-slate-50"
157	              }`}
158	            >
159	              {idx + 1}
160	            </button>
161	          ))}
162	
163	          <button
164	            onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
165	            disabled={currentPage === totalPages}
166	            className="p-2 border border-slate-200 rounded-xl bg-white text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
167	          >
168	            <ChevronRight className="w-5 h-5" />
169	          </button>
170	        </div>
171	      )}
172	    </div>
173	  );
174	}
