1	import { randomUUID } from "node:crypto";
2	import { getCurrentUser } from "@/lib/auth";
3	import { prisma } from "@/lib/prisma";
4	import { CheckoutInput, CheckoutInputSchema } from "@/lib/validations";
5	import { computeCartTotals } from "@/lib/cart";
6	
7	export async function createOrder(sessionId: string, rawInput: unknown) {
8	  const parseResult = CheckoutInputSchema.safeParse(rawInput);
9	  if (!parseResult.success) {
10	    throw new Error(parseResult.error.issues.map((issue) => issue.message).join(", "));
11	  }
12	
13	  const input: CheckoutInput = parseResult.data;
14	  const user = await getCurrentUser();
15	
16	  // UUID entropy avoids the small, fixed order-number space of the old four-digit suffix.
17	  const orderNumber = `KM-${new Date().getFullYear()}-${randomUUID().toUpperCase()}`;
18	
19	  // Execute inside a transaction to ensure atomicity and stock decrement
20	  const order = await prisma.$transaction(async (tx) => {
21	    const cart = await tx.cart.findUnique({
22	      where: { sessionId },
23	      include: {
24	        items: {
25	          include: { variant: { include: { product: true } } },
26	        },
27	      },
28	    });
29	
30	    if (!cart || cart.items.length === 0) {
31	      throw new Error("Votre panier est vide");
32	    }
33	
34	    // Claim the exact cart snapshot before consuming stock. Concurrent checkout
35	    // requests can only claim these rows once; failures roll the deletion back.
36	    const claimedItems = await tx.cartItem.deleteMany({
37	      where: {
38	        cartId: cart.id,
39	        OR: cart.items.map(({ id, quantity, updatedAt }) => ({ id, quantity, updatedAt })),
40	      },
41	    });
42	    if (claimedItems.count !== cart.items.length) {
43	      throw new Error("Votre panier a changé. Veuillez réessayer.");
44	    }
45	
46	    const { shippingCost, total } = computeCartTotals(cart);
47	
48	    // 1. Verify stock & deduct
49	    for (const item of cart.items) {
50	      const stockUpdate = await tx.productVariant.updateMany({
51	        where: {
52	          id: item.variantId,
53	          stock: { gte: item.quantity },
54	        },
55	        data: { stock: { decrement: item.quantity } },
56	      });
57	
58	      if (stockUpdate.count !== 1) {
59	        throw new Error(`Stock insuffisant pour le produit: ${item.variant.nameFr}`);
60	      }
61	
62	      const inventory = await tx.inventory.findUnique({
63	        where: { productId: item.variant.productId },
64	        select: { productId: true },
65	      });
66	      if (inventory) {
67	        const inventoryUpdate = await tx.inventory.updateMany({
68	          where: {
69	            productId: item.variant.productId,
70	            stock: { gte: item.quantity },
71	          },
72	          data: { stock: { decrement: item.quantity } },
73	        });
74	        if (inventoryUpdate.count !== 1) {
75	          throw new Error(`Stock insuffisant pour le produit: ${item.variant.nameFr}`);
76	        }
77	      }
78	    }
79	
80	    // 2. Create Order
81	    const newOrder = await tx.order.create({
82	      data: {
83	        orderNumber,
84	        ...(user ? { userId: user.id } : {}),
85	        customerName: input.customerName,
86	        customerPhone: input.customerPhone,
87	        customerEmail: input.customerEmail || null,
88	        shippingAddress: input.shippingAddress,
89	        city: input.city,
90	        totalAmount: total,
91	        shippingCost: shippingCost,
92	        paymentMethod: input.paymentMethod,
93	        paymentStatus: "PENDING",
94	        status: "PENDING",
95	        items: {
96	          create: cart.items.map((item) => ({
97	            productId: item.variant.productId,
98	            variantId: item.variantId,
99	            quantity: item.quantity,
100	            unitPrice: Number(item.variant.price ?? item.variant.product.price),
101	          })),
102	        },
103	      },
104	      include: { items: true },
105	    });
106	
107	    return newOrder;
108	  });
109	
110	  return order;
111	}
